import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;
import org.springframework.data.redis.core.StringRedisTemplate;

import java.util.concurrent.TimeUnit;

/**
 * 多级缓存 + Cache Aside + 防击穿 + 防穿透
 */
public class MultiLevelCacheService {

    private final Cache<String, Object> localCache = Caffeine.newBuilder()
            .maximumSize(10_000)
            .expireAfterWrite(30, TimeUnit.SECONDS) // L1 TTL 短
            .build();

    private final StringRedisTemplate redis;
    private final UserMapper userMapper;

    // ========== 读链路：L1 → L2 → DB，逐级回源 ==========
    public UserDTO getUser(String userId) {
        // L1 本地缓存
        UserDTO user = (UserDTO) localCache.getIfPresent(userId);
        if (user != null) return user;

        // L2 Redis
        String cacheKey = "user:" + userId;
        String json = redis.opsForValue().get(cacheKey);
        if (json != null) {
            if ("NULL".equals(json)) return null; // 空值缓存防穿透
            user = JSON.parseObject(json, UserDTO.class);
            localCache.put(userId, user); // 回填 L1
            return user;
        }

        // 查 DB（防击穿：分布式锁）
        user = loadFromDbWithLock(userId, cacheKey);
        if (user != null) {
            localCache.put(userId, user);
        }
        return user;
    }

    // ========== 防击穿：分布式锁 + 双重检查 ==========
    private UserDTO loadFromDbWithLock(String userId, String cacheKey) {
        String lockKey = "lock:user:" + userId;
        boolean locked = redis.opsForValue()
                .setIfAbsent(lockKey, "1", 10, TimeUnit.SECONDS);
        if (locked) {
            try {
                // 双重检查：拿到锁后可能其他线程已回填
                String json = redis.opsForValue().get(cacheKey);
                if (json != null) {
                    return "NULL".equals(json) ? null : JSON.parseObject(json, UserDTO.class);
                }
                UserDTO user = userMapper.selectById(userId);
                if (user == null) {
                    // 防穿透：缓存空值，短 TTL
                    redis.opsForValue().set(cacheKey, "NULL", 5, TimeUnit.MINUTES);
                } else {
                    redis.opsForValue().set(cacheKey,
                            JSON.toJSONString(user), 30, TimeUnit.MINUTES);
                }
                return user;
            } finally {
                redis.delete(lockKey);
            }
        }
        // 未获锁：短暂等待后重试（从缓存读）
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return getUser(userId);
    }

    // ========== 写链路：Cache Aside（先更 DB 再删缓存） ==========
    public void updateUser(String userId, UserUpdateCmd cmd) {
        // 1. 先更新 DB
        userMapper.updateById(userId, cmd);
        // 2. 再删 Redis
        redis.delete("user:" + userId);
        // 3. 失效广播，通知其他实例清除 L1
        redis.convertAndSend("cache:invalidate", userId);
    }
}

// ========== 延迟双删 ==========
public class DelayDoubleDeleteService {

    public void updateUserWithDelayDelete(String userId, UserUpdateCmd cmd) {
        String cacheKey = "user:" + userId;
        // 第一次删除
        redis.delete(cacheKey);
        // 更新 DB
        userMapper.updateById(userId, cmd);
        // 延迟后第二次删除（覆盖并发读回填的旧值）
        CompletableFuture.delayedExecutor(500, TimeUnit.MILLISECONDS)
                .execute(() -> redis.delete(cacheKey));
    }
}

// ========== 过期时间随机抖动防雪崩 ==========
public class CacheTtlHelper {
    private static final Random RANDOM = new Random();

    /** 基础 TTL + 0~300s 随机抖动 */
    public static long randomTtl(long baseSeconds) {
        return baseSeconds + RANDOM.nextInt(300);
    }
}
